changeSet.sql:
UPDATE utm_visualization SET filters = REPLACE(REPLACE(REPLACE(REPLACE(filters, '"severityLabel.keyword"', '"severityLabel"'), '"statusLabel.keyword"', '"statusLabel"'), '"statusObservation.keyword"', '"statusObservation"'), '"id.keyword"', '"id"') WHERE (id_pattern = 2 OR event_type = 'alert-*') AND filters IS NOT NULL AND (filters LIKE '%severityLabel.keyword%' OR filters LIKE '%statusLabel.keyword%' OR filters LIKE '%statusObservation.keyword%' OR filters LIKE '%id.keyword%');
UPDATE utm_visualization SET aggregation = REPLACE(REPLACE(REPLACE(REPLACE(aggregation, '"severityLabel.keyword"', '"severityLabel"'), '"statusLabel.keyword"', '"statusLabel"'), '"statusObservation.keyword"', '"statusObservation"'), '"id.keyword"', '"id"') WHERE (id_pattern = 2 OR event_type = 'alert-*') AND aggregation IS NOT NULL AND (aggregation LIKE '%severityLabel.keyword%' OR aggregation LIKE '%statusLabel.keyword%' OR aggregation LIKE '%statusObservation.keyword%' OR aggregation LIKE '%id.keyword%');
UPDATE utm_visualization SET query = REPLACE(REPLACE(REPLACE(REPLACE(query, '"severityLabel.keyword"', '"severityLabel"'), '"statusLabel.keyword"', '"statusLabel"'), '"statusObservation.keyword"', '"statusObservation"'), '"id.keyword"', '"id"') WHERE (id_pattern = 2 OR event_type = 'alert-*') AND query IS NOT NULL AND (query LIKE '%severityLabel.keyword%' OR query LIKE '%statusLabel.keyword%' OR query LIKE '%statusObservation.keyword%' OR query LIKE '%id.keyword%');
UPDATE utm_visualization SET filters = REPLACE(REPLACE(filters, '"value":"Close"', '"value":"Completed"'), '"value": "Close"', '"value": "Completed"') WHERE id = 500 AND filters IS NOT NULL AND (filters LIKE '%"value":"Close"%' OR filters LIKE '%"value": "Close"%');
